package driver

import (
	"fmt"
	"time"
)

const (
	// farePerMinute is the price charged for each minute of route ETA.
	farePerMinute = 1.50
	// minimumFare is the lowest fare we ever charge.
	minimumFare = 3.50
)

// calculateFare computes the fare in dollars for a route with the given ETA.
func calculateFare(eta time.Duration) float64 {
	fare := eta.Minutes() * farePerMinute
	if fare < minimumFare {
		return minimumFare
	}
	return fare
}

// formatFare renders a fare as a dollar amount, e.g. "$4.50".
func formatFare(fare float64) string {
	return fmt.Sprintf("$%.2f", fare)
}
