// retryRideHistory reports whether a ride_history query that failed with err
// should be retried, creating the ride_history table if it is missing.
func (d *database) retryRideHistory(err error) bool {
	if mysqlErr, ok := err.(*mysql.MySQLError); ok && mysqlErr.Number == 1146 {
		return d.setupRideHistory() == nil
	}
	return false
