func (d *database) CreateRideHistory(ctx context.Context, entry *RideHistoryEntry) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Creating ride history entry")

	var id int64
	err := d.withRideHistoryRetry(func() error {
		res, err := d.db.Exec("INSERT INTO ride_history "+
			"(pickup_location, dropoff_location, request_time, driver_plate, fare) VALUES (?, ?, ?, ?, ?)",
			entry.PickupLocation, entry.DropoffLocation, entry.RequestTime.UTC(), entry.DriverPlate, entry.Fare)
