var ErrRideNotFound = errors.New("ride history entry not found")

// GetRideHistory returns a single ride history entry.
func (d *database) GetRideHistory(ctx context.Context, id int64) (*RideHistoryEntry, error) {
	var e *RideHistoryEntry
	err := d.withRideHistoryRetry(func() error {
		var err error
		e, err = scanRideHistory(d.db.QueryRow(
			"SELECT "+rideHistoryColumns+" FROM ride_history WHERE id = ?", id))
		return err
	})
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrRideNotFound
	}
	if err != nil {
		return nil, err
	}
	return e, nil
}

// UpdateRideHistory sets the driver plate and fare of an existing ride.
func (d *database) UpdateRideHistory(ctx context.Context, id int64, plate string, fare float64) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Updating ride history entry", zap.Int64("id", id))

	err := d.withRideHistoryRetry(func() error {
		_, err := d.db.Exec("UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?", plate, fare, id)
		return err
	})
	if err != nil {
		return nil, err
	}
	// RowsAffected is 0 when the values didn't change, so look the row up
	// instead to tell whether it exists.
	return d.GetRideHistory(ctx, id)
}
