        try {
            const entry = await apiPostStrict<RideHistoryEntry>('/ride-history', {
                pickupLocation,
                dropoffLocation,
                requestTime: requestTime.toISOString(),
            });
            await refresh();
            return entry.id;
        } catch (e) {
            console.error('cannot create ride history entry', e);
            return undefined;
        }
    }, [refresh]);

    const updateEntry = useCallback(async (id: number, driverPlate: string, fare: number) => {
